```st
(* ENGINEERING_CONTRACT
- valveOpen: rises only on start edge from not filling (idle/pending), stays open while accumulating below target; closes same scan when accum>=target or reset edge. Same-scan reset priority over start/flow/confirm.
- fillsToday: increments only when local_pending AND doneSensor; reset edge zeroes same scan; saturates at 32767 while still clearing local_pending.
- local_pending: set when target reached; cleared by confirm, reset, or start of new bottle (cancel prior pending first).
- local_accum: zeroed on reset or new bottle start; adds flowVol only while local_filling, including start scan.
- local_filling: represents actual filling process; start edge opens/sets, threshold closes/clears.
- Edge memory tmp_prevStart/tmp_prevReset false before first call.
- S1-S14: mapping per task; units mL REAL, counts INT; threshold >=; same-scan immediate confirmation after closing.
*)
(* CONTRACT_RULES [] *)
FUNCTION_BLOCK FB
VAR_INPUT
    startBtn : BOOL;
    resetBtn : BOOL;
    doneSensor : BOOL;
    targetVol : REAL;
    flowVol : REAL;
END_VAR
VAR_OUTPUT
    valveOpen : BOOL := FALSE;
    fillsToday : INT := 0;
END_VAR
VAR
    tmp_prevStart : BOOL := FALSE;
    tmp_prevReset : BOOL := FALSE;
    local_accum : REAL := 0.0;
    local_filling : BOOL := FALSE;
    local_pending : BOOL := FALSE;
    local_startR : BOOL;
    local_resetR : BOOL;
END_VAR

local_startR := startBtn AND NOT tmp_prevStart;
local_resetR := resetBtn AND NOT tmp_prevReset;

IF local_resetR THEN
    valveOpen := FALSE;
    fillsToday := 0;
    local_accum := 0.0;
    local_filling := FALSE;
    local_pending := FALSE;
ELSE
    IF local_startR AND NOT local_filling THEN
        local_pending := FALSE;
        local_filling := TRUE;
        valveOpen := TRUE;
        local_accum := 0.0;
    END_IF;

    IF local_filling THEN
        local_accum := local_accum + flowVol;
        IF local_accum >= targetVol THEN
            local_filling := FALSE;
            valveOpen := FALSE;
            local_pending := TRUE;
        END_IF;
    END_IF;

    IF local_pending AND doneSensor THEN
        IF fillsToday < 32767 THEN
            fillsToday := fillsToday + 1;
        END_IF;
        local_pending := FALSE;
    END_IF;
END_IF;

tmp_prevStart := startBtn;
tmp_prevReset := resetBtn;
END_FUNCTION_BLOCK
```

